import {startParticles} from './particles.js';
import {predict} from './inference.js';
startParticles();
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slug=n=>n.toLowerCase().replaceAll(' ','_').replaceAll('-','_');
const short=n=>n.replace(' Regression','').replace('Support Vector Machine','SVC').replace('Support Vector','SVR').replace('K-Nearest Neighbors','KNN').replace('Gradient Boosting','Gradient Boosting');
const pretty=s=>s.replaceAll('__',' / ').replaceAll('_',' ').replace(/\b\w/g,v=>v.toUpperCase());
const number=(v,d=4)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const state={track:'regression',tab:'overview',metric:'R2',stage:'Tuned',models:new Set(),detail:null,sortReverse:false,filter:'All',allPlots:false,predictModel:null};
const dataCache=new Map(),modelCache=new Map();let catalog,currentData,loadSerial=0;
const names=d=>d.models.map(m=>m.name),rowname=r=>r.Model||r.Algorithm;
const definition=m=>catalog?.metric_definitions[m]||{direction:'higher',unit:'score',definition:''};
function format(v,m){if(v==null||!Number.isFinite(Number(v)))return '—';return definition(m).unit==='fraction'?number(v*100,2)+'%':number(v,m==='RMSE'||m==='MAE'?2:4)}
function delta(v,m){return (v>0?'+':'')+(definition(m).unit==='fraction'?number(v*100,3)+' pp':number(v,4))}
const direction=m=>definition(m).direction==='lower'?'Lower is better ↓':'Higher is better ↑';
function toast(text){const e=$('#toast');e.textContent=text;e.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('visible'),2800)}
async function fetchJSON(url){const r=await fetch(url);if(!r.ok)throw Error('Could not load '+url);return r.json()}
async function loadTrack(track,scroll=false){
 const serial=++loadSerial;state.track=track;state.detail=null;state.predictModel=null;state.stage='Tuned';state.sortReverse=false;state.filter='All';state.allPlots=false;
 $$('#lab [data-lab-track]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.labTrack===track)));
 $('#lab-content').innerHTML='<div class="loading"><span class="loader"></span>Opening the evidence…</div>';
 try{if(!dataCache.has(track))dataCache.set(track,await fetchJSON(`data/${track}.json`));if(serial!==loadSerial)return;currentData=dataCache.get(track);state.metric=currentData.metrics[0];state.models=new Set(names(currentData));state.detail=currentData.models[0].name;state.predictModel=selectedName(currentData);renderSummary();render();$('#data-status').textContent='SOURCE RESULTS VERIFIED';if(scroll)$('#lab').scrollIntoView({behavior:'smooth'})}
 catch(error){if(serial===loadSerial)$('#lab-content').innerHTML=`<div class="model-empty">${esc(error.message)}. <button class="text-button" data-retry>Retry</button></div>`}
}
function selectedName(d){return d.selection?.selected_model||d.selection?.model||'K-Means'}
function renderSummary(){const d=currentData,ds=d.dataset;$('#track-summary').innerHTML=`<span>DATASET <b>${esc(d.subject.toUpperCase())}</b></span><span>RAW ROWS <b>${ds.rows.toLocaleString()}</b></span><span>CLEANED ROWS <b>${ds.cleaned_rows.toLocaleString()}</b></span><span>${state.track==='clustering'?'FITTING COHORT':'TRAIN / TEST'} <b>${state.track==='clustering'?ds.fitting_rows.toLocaleString():ds.training_rows+' / '+ds.test_rows}</b></span><span>MODELS <b>${d.models.length.toString().padStart(2,'0')}</b></span>`}
function openTab(tab,scroll=false){state.tab=tab;render();if(scroll)$('#lab').scrollIntoView({behavior:'smooth'})}
function render(){if(!currentData)return;$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);if(b.dataset.tab===state.tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#lab-content').innerHTML=({overview:overview,compare:compare,models:modelDetail,plots:plots,predict:prediction}[state.tab])();bindContent()}
function metricsCards(row,metrics=currentData.metrics){return `<div class="metrics">${metrics.map(m=>`<div class="metric-card"><span>${esc(m.toUpperCase().replace('F1_WEIGHTED','WEIGHTED F1'))}</span><strong>${format(row[m],m)}</strong><small>${direction(m)}</small></div>`).join('')}</div>`}
function dataTable(rows,columns,{numeric=[],labels={},sort=false}={}){return `<div class="data-wrap"><table><thead><tr>${columns.map(c=>`<th>${sort?`<button data-sort="${esc(c)}">${esc(labels[c]||c)} ${c===state.metric?'↕':''}</button>`:esc(labels[c]||c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>`<td class="${numeric.includes(c)?'number':''}">${numeric.includes(c)?format(row[c],c):esc(row[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function downloads(){return `<div class="download-row"><a href="downloads/${state.track}_comparison.csv" download>Download comparison CSV ↗</a><a href="downloads/${state.track}.ipynb" download>Download track notebook ↗</a><a href="downloads/README.md" download>Read project notes ↗</a><a href="downloads/verification.json" download>Read verification report ↗</a></div>`}
function overview(){const d=currentData,selected=selectedName(d),row=d.comparison.find(r=>rowname(r)===selected)||d.comparison[0],clust=state.track==='clustering';
 const explanation={regression:'Estimate a diamond’s price from its physical dimensions and quality categories. Ten regressors share the same cleaned dataset and held-out test rows.',classification:'Distinguish two rice classes from grain measurements. Ten classifiers share one stratified split, with errors and probabilities available for inspection.',clustering:'Discover customer groups without training on campaign outcomes. Compare two methods on the same transformed cohort.'}[state.track];
 return `<div class="panel-head"><div><h3>${esc(d.subject)}. A question worth exploring.</h3><p>${explanation}</p></div><span class="badge dark">${clust?'FITTED COHORT':'HELD-OUT EVALUATION'}</span></div><div class="subheading">${clust?'K-Means at a glance':'CV-selected model: '+esc(selected)}</div>${metricsCards(row)}<div class="info-grid"><div class="info-card"><div class="micro">01 / THE DATA</div><h4>${d.dataset.rows.toLocaleString()} original observations.</h4><p>${d.dataset.columns} source columns. ${d.dataset.cleaned_rows.toLocaleString()} rows after cleaning. ${clust?'No target labels enter model fitting.':`Target: ${esc(d.dataset.target)}. ${d.dataset.test_rows} rows reserved for testing.`}</p></div><div class="info-card"><div class="micro">02 / THE METHOD</div><h4>${clust?'Structure without labels.':'A common ground for comparison.'}</h4><p>${clust?'The same imputation, clipping, scaling and encoding are used for both algorithms. K comes from the geometric elbow knee.':'Seed 42. One 80:20 split. Fitted preprocessing stays inside each training fold; the test set is held out during tuning.'}</p></div><div class="info-card"><div class="micro">03 / YOUR NEXT STEP</div><h4>Make the comparison your own.</h4><p>Select a metric, compare models, inspect a plot or enter a new ${clust?'customer profile':state.track==='regression'?'diamond':'grain'} to see an actual model result.</p><button class="text-button" data-jump="compare">Compare models →</button></div></div><details><summary>How are these results evaluated?</summary><p>${clust?'Silhouette measures cohesion and separation; Davies-Bouldin measures cluster scatter relative to separation; Calinski-Harabasz compares between- and within-cluster dispersion. Five-fold subset refits report metric variation and adjusted Rand stability. These are unsupervised checks, not held-out classification accuracy. Campaign response is excluded from training.':'Hyperparameters are selected by five-fold training cross-validation. The deployment model is selected by '+(state.track==='regression'?'training CV R²':'training CV weighted F1')+'. The comparison reports untouched test results. CV folds reused for tuning are not an unbiased nested-CV estimate. The test-metric winner and CV-selected model can differ.'}</p><p>${state.track==='regression'?'Volume is computed from x × y × z. Numeric predictors use fold-fitted median imputation, IQR clipping and scaling; quality categories are one-hot encoded. SVR also scales its target inside training folds. Prices are in dataset units; currency has not been verified.':state.track==='classification'?'Compactness is computed as 4π × Area / (Perimeter² + 10⁻⁸). Precision, recall and F1 use class-support weighting. Class labels 0 and 1 are retained because variety names were not supplied.':'Age and tenure use the historical dataset reference ('+esc(d.reference_date)+'). Outcomes are inspected only after fitting. Agglomerative clustering has no native prediction method for a new customer.'}</p></details><div class="subheading">A look at the source data</div>${dataTable(d.dataset.preview,Object.keys(d.dataset.preview[0]))}<p class="quiet-note">${clust?'PCA and t-SNE are projections for inspection, not the space used to compute cluster metrics.':'Model performance describes this held-out sample. Compare several metrics rather than treating one score as a complete picture.'}</p>${downloads()}`;
}
function metricOptions(){return currentData.metrics.map(m=>`<option value="${esc(m)}" ${m===state.metric?'selected':''}>${esc(m.replace('F1_weighted','Weighted F1'))}</option>`).join('')}
function displayRow(model){const row={...model.metrics};if(state.stage==='Baseline')for(const item of model.tuning||[])row[item.Metric]=item.Baseline;return row}
function selectedRows(){return currentData.models.filter(m=>state.models.has(m.name)).map(m=>({...displayRow(m),_name:m.name})).sort((a,b)=>(definition(state.metric).direction==='lower'?1:-1)*(state.sortReverse?-1:1)*(a[state.metric]-b[state.metric]))}
function compare(){const d=currentData,rows=selectedRows(),clust=state.track==='clustering';return `<div class="panel-head"><div><h3>Different approaches. One fair comparison.</h3><p>Choose a metric and a set of models. Every score below comes from the same ${clust?'preprocessed cohort':'held-out split'}.</p></div><span class="badge">${clust?'INTERNAL VALIDATION':state.stage.toUpperCase()+' MODELS'}</span></div><div class="toolbar"><div><label class="control-label" for="metric-select">COMPARE BY</label><select id="metric-select">${metricOptions()}</select></div>${!clust?`<div class="segmented" aria-label="Evaluation stage"><button data-stage-model="Tuned" class="${state.stage==='Tuned'?'active':''}">Tuned</button><button data-stage-model="Baseline" class="${state.stage==='Baseline'?'active':''}">Baseline</button></div>`:''}<div class="micro">${direction(state.metric).toUpperCase()}</div></div><p class="quiet-note">${esc(definition(state.metric).definition)}</p><div class="model-checks">${d.models.map(m=>`<label><input type="checkbox" data-check-model="${esc(m.name)}" ${state.models.has(m.name)?'checked':''}>${esc(short(m.name))}</label>`).join('')}</div>${rows.length?barChart(rows.map(r=>({name:short(r._name),value:r[state.metric]})),state.metric):'<div class="model-empty">Choose at least one model to compare.</div>'}${rows.length?dataTable(rows.map(r=>({...r,Model:r._name})),['Model',...d.metrics],{numeric:d.metrics,labels:{F1_weighted:'Weighted F1',ROC_AUC:'ROC-AUC'},sort:true}):''}${d.models.length>=2?`<div class="pair-box"><div class="micro">A CLOSER COMPARISON / ${esc(state.metric.toUpperCase())}</div><div class="pair-controls"><select id="pair-a" aria-label="First comparison model">${d.models.map(m=>`<option>${esc(m.name)}</option>`).join('')}</select><span class="micro">VS</span><select id="pair-b" aria-label="Second comparison model">${d.models.map((m,i)=>`<option ${i===1?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div id="pair-result" class="pair-result"></div></div>`:''}${clust?`<div class="subheading">What changes with linkage?</div>${dataTable(d.linkages,['Linkage','Clusters','Minimum_cluster_size',...d.metrics],{numeric:d.metrics})}<p class="quiet-note">Selection rule: ${esc(d.linkage_selection_rule)}. A large silhouette alone can favor small outlier groups; cluster size is shown alongside it.</p>`:'<p class="quiet-note">The baseline/tuned switch changes held-out metric values. Hyperparameter selection uses training CV; a tuned model may improve some test metrics while worsening others.</p>'}${downloads()}`}
function barChart(rows,metric){const max=Math.max(...rows.map(r=>Math.abs(r.value)),.0001),min=Math.min(0,...rows.map(r=>r.value)),height=rows.length*35+22,left=185,width=900,plot=width-left-130;return `<div class="chart-frame"><div class="micro"><span>${esc(metric.toUpperCase())} / ${state.tab==='compare'&&state.track!=='clustering'?state.stage.toUpperCase():'FITTED RESULTS'}</span><span>${catalog?.metric_definitions[metric]?direction(metric):metric==='Customers'?'COHORT DISTRIBUTION':'RELATIVE IMPORTANCE'}</span></div><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(metric)} by model">${rows.map((r,i)=>{const y=15+i*35,w=Math.max(1,Math.abs(r.value)/max*plot);return `<text x="0" y="${y+13}" fill="#555" font-size="11">${esc(r.name)}</text><rect x="${left}" y="${y}" width="${w}" height="20" fill="${i===0?'#111':'#bfc2b8'}"/><text x="${left+w+12}" y="${y+14}" fill="#555" font-size="11">${format(r.value,metric)}</text>`}).join('')}${min<0?`<text x="0" y="${height}" font-size="9" fill="#999">Negative scores are shown with their signed values.</text>`:''}</svg></div>`}
function pairResult(){if(!$('#pair-a'))return;const a=currentData.models.find(m=>m.name===$('#pair-a').value),b=currentData.models.find(m=>m.name===$('#pair-b').value),av=displayRow(a)[state.metric],bv=displayRow(b)[state.metric],diff=av-bv,better=definition(state.metric).direction==='lower'?diff<0:diff>0;$('#pair-result').innerHTML=`<strong>${esc(a.name)}</strong>: ${format(av,state.metric)} &nbsp; / &nbsp; <strong>${esc(b.name)}</strong>: ${format(bv,state.metric)}<br>${Math.abs(diff)<1e-12?'The models have the same score for this metric.':`Absolute difference: <strong>${definition(state.metric).unit==='fraction'?number(Math.abs(diff)*100,3)+' percentage points':number(Math.abs(diff),4)}</strong>. ${esc(better?a.name:b.name)} has the better ${esc(state.metric)} score.`}`}
function modelOptions(selected,models=currentData.models){return models.map(m=>`<option value="${esc(m.name)}" ${m.name===selected?'selected':''}>${esc(m.name)}</option>`).join('')}
function modelDetail(){const d=currentData,m=d.models.find(m=>m.name===state.detail)||d.models[0],clust=state.track==='clustering',params=m.parameters||{},row=m.metrics;return `<div class="panel-head"><div><h3>Look a little closer.</h3><p>Inspect the fitted model, its parameters, validation and the errors it makes.</p></div><select class="model-selector" id="detail-select" aria-label="Model detail">${modelOptions(m.name)}</select></div>${metricsCards(row)}${clust?clusterDetail(m):`<div class="subheading">Selected hyperparameters</div>${Object.keys(params).length?`<div class="parameter-grid">${Object.entries(params).map(([k,v])=>`<div class="parameter"><span class="micro">${esc(pretty(k.replace('model__','').replace('regressor__','').replace('preprocessor__num__polynomial__','')))}</span>${esc(Array.isArray(v)?v.join(' × '):v===null?'Unlimited':v)}</div>`).join('')}</div>`:'<p class="quiet-note">A fixed linear baseline. No hyperparameter search is required.</p>'}<div class="subheading">Before and after tuning</div>${tuningTable(m)}${state.track==='classification'?classificationDiagnostics(m):regressionDiagnostics(m)}${m.feature_importance?`<div class="subheading">What the fitted model uses</div>${barChart(m.feature_importance.map(v=>({name:v.Feature,value:v.Importance})).sort((a,b)=>b.value-a.value).slice(0,12),'Feature importance')}<p class="quiet-note">Tree importance reflects split usefulness in this fitted model, not a causal effect. Correlated inputs can share or redistribute importance.</p>`:''}${m.coefficients?`<div class="subheading">${m.name==='Lasso Regression'?`Coefficient sparsity / ${m.zero_coefficient_count} near-zero coefficients`:'Fitted coefficients'}</div>${dataTable([...m.coefficients].sort((a,b)=>Math.abs(b.Coefficient)-Math.abs(a.Coefficient)).slice(0,15),Object.keys(m.coefficients[0]),{numeric:['Coefficient','Odds_ratio']})}<p class="quiet-note">Coefficients are conditional on the other transformed inputs. Numeric inputs have been scaled; category coefficients refer to encoded levels.</p>`:''}${m.training_loss_curve?`<div class="subheading">MLP training loss</div>${lineChart(m.training_loss_curve.map((y,i)=>[i+1,y]),'Iteration','Training loss')}`:''}<div class="subheading">Five-fold training validation</div>${cvDisplay(m)}<details><summary>View the full search results (${m.search.length} configurations)</summary>${dataTable(m.search.map(r=>({Parameters:r.params,'Mean CV score':r.mean_test_score,'CV standard deviation':r.std_test_score,Rank:r.rank_test_score})),['Parameters','Mean CV score','CV standard deviation','Rank'],{numeric:['Mean CV score','CV standard deviation']})}</details>`}${downloads()}`}
function tuningTable(m){return `<div class="data-wrap"><table><thead><tr><th>METRIC</th><th>BASELINE</th><th>TUNED</th><th>CHANGE</th></tr></thead><tbody>${m.tuning.map(r=>{const better=definition(r.Metric).direction==='lower'?r.Change<0:r.Change>0;return `<tr><td>${esc(r.Metric)}</td><td class="number">${format(r.Baseline,r.Metric)}</td><td class="number">${format(r.Tuned,r.Metric)}</td><td class="number ${Math.abs(r.Change)<1e-12?'':better?'positive':'negative'}">${delta(r.Change,r.Metric)}</td></tr>`}).join('')}</tbody></table></div>`}
function regressionDiagnostics(m){const p=m.predictions;return `<div class="two-column">${scatterChart(p.map(r=>[r.actual,r.predicted]),'Actual price','Predicted price','Predicted versus actual',true)}${scatterChart(p.map(r=>[r.predicted,r.residual]),'Predicted price','Actual − predicted','Residuals',false,true)}</div>`}
function classificationDiagnostics(m){const p=m.predictions,labels=currentData.class_labels,cm=labels.map(()=>labels.map(()=>0));p.forEach(r=>cm[labels.indexOf(r.actual)][labels.indexOf(r.predicted)]++);const max=Math.max(...cm.flat());let svg='';cm.forEach((row,i)=>row.forEach((v,j)=>{svg+=`<rect x="${120+j*100}" y="${35+i*100}" width="100" height="100" fill="rgba(20,30,20,${.04+v/max*.9})"/><text x="${170+j*100}" y="${90+i*100}" text-anchor="middle" font-size="18" fill="${v/max>.5?'white':'#222'}">${v}</text>`}));const order=[...p].sort((a,b)=>b.probability_1-a.probability_1),positive=order.filter(r=>r.actual===1).length,negative=order.length-positive;let tp=0,fp=0;const roc=[[0,0]];for(let i=0;i<order.length;i++){order[i].actual===1?tp++:fp++;if(i===order.length-1||order[i+1].probability_1!==order[i].probability_1)roc.push([fp/negative,tp/positive])}return `<div class="two-column"><div class="chart-frame"><div class="micro">HELD-OUT CONFUSION MATRIX</div><svg viewBox="0 0 440 300" role="img" aria-label="Confusion matrix">${svg}<text x="220" y="285" text-anchor="middle" font-size="12">Predicted class</text><text transform="translate(45,150) rotate(-90)" text-anchor="middle" font-size="12">Actual class</text>${labels.map((l,i)=>`<text x="${170+i*100}" y="257" text-anchor="middle" font-size="12">${l}</text><text x="103" y="${90+i*100}" font-size="12">${l}</text>`).join('')}</svg></div>${lineChart(roc,'False positive rate','True positive rate','ROC / AUC '+format(m.metrics.ROC_AUC,'ROC_AUC'),true)}</div>`}
function cvDisplay(m){const best=[...m.search].sort((a,b)=>b.mean_test_score-a.mean_test_score)[0];if(!best)return '';const values=Array.from({length:5},(_,i)=>({Fold:i+1,Score:best['split'+i+'_test_score']}));return dataTable(values,['Fold','Score'],{numeric:['Score']})+`<p class="quiet-note">Training CV ${state.track==='regression'?'R²':'weighted F1'} for the selected configuration. These folds were used during tuning; they are not a separate nested-CV estimate.</p>`}
function clusterDetail(m){const d=currentData;return `<div class="subheading">Customer profile by cluster</div>${dataTable(m.profiles,Object.keys(m.profiles[0]),{numeric:Object.keys(m.profiles[0]).filter(c=>!['Cluster','Customers'].includes(c))})}<p class="quiet-note">Means are in original feature units. Age and tenure reference ${esc(d.reference_date)}. Cluster numbers identify fitted groups; they are not invented customer personas.</p><div class="subheading">Cluster sizes</div>${barChart(Object.entries(m.cluster_sizes).map(([k,v])=>({name:'Cluster '+k,value:v})),'Customers')}<div class="subheading">Five-fold subset refits</div>${dataTable(m.resampling,['Fold',...d.metrics,'ARI_vs_full_fit'],{numeric:[...d.metrics,'ARI_vs_full_fit']})}<p class="quiet-note">Each fold refits preprocessing and the clustering model on 80% of the cohort. Adjusted Rand compares that subset’s labels with the full fit. This is stability validation, not held-out predictive accuracy.</p>${m.name==='K-Means'?lineChart(d.elbow.map(r=>[r.k,r.Inertia]),'Clusters (k)','Inertia','K-Means elbow / geometric knee: k='+m.metrics.Clusters):`<div class="subheading">Linkage comparison</div>${dataTable(d.linkages,Object.keys(d.linkages[0]),{numeric:d.metrics})}<p class="quiet-note">${esc(d.linkage_selection_rule)}. The selected linkage is ${esc(m.metrics.Linkage)}. Inspect its dendrogram in the plot explorer.</p>`}`}
function scatterChart(points,xlabel,ylabel,title,diagonal=false,zero=false){const w=500,h=335,l=68,r=24,t=15,b=55;let xmin=Math.min(0,...points.map(p=>p[0])),xmax=Math.max(...points.map(p=>p[0])),ymin=Math.min(0,...points.map(p=>p[1])),ymax=Math.max(...points.map(p=>p[1]));if(diagonal){xmin=ymin=Math.min(xmin,ymin);xmax=ymax=Math.max(xmax,ymax)}const xp=x=>l+(x-xmin)/(xmax-xmin||1)*(w-l-r),yp=y=>h-b-(y-ymin)/(ymax-ymin||1)*(h-t-b);return `<div class="chart-frame"><div class="micro">${esc(title)}</div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}">${axes(w,h,l,r,t,b,xmin,xmax,ymin,ymax,xlabel,ylabel)}${diagonal?`<path d="M${xp(xmin)},${yp(xmin)}L${xp(xmax)},${yp(xmax)}" stroke="#aaa" stroke-dasharray="5 4" fill="none"/>`:''}${zero?`<path d="M${l},${yp(0)}H${w-r}" stroke="#aaa" stroke-dasharray="5 4"/>`:''}${points.map(p=>`<circle cx="${xp(p[0])}" cy="${yp(p[1])}" r="2" fill="#30382c" opacity=".38"/>`).join('')}</svg></div>`}
function axes(w,h,l,r,t,b,xmin,xmax,ymin,ymax,xlabel,ylabel){return Array.from({length:5},(_,i)=>{const x=l+i*(w-l-r)/4,y=h-b-i*(h-t-b)/4;return `<path d="M${x},${t}V${h-b}M${l},${y}H${w-r}" stroke="#eceee8"/><text x="${x}" y="${h-b+18}" text-anchor="middle" fill="#999" font-size="9">${tick(xmin+(xmax-xmin)*i/4)}</text><text x="${l-8}" y="${y+3}" text-anchor="end" fill="#999" font-size="9">${tick(ymin+(ymax-ymin)*i/4)}</text>`}).join('')+`<text x="${(l+w-r)/2}" y="${h-8}" text-anchor="middle" font-size="11" fill="#666">${esc(xlabel)}</text><text transform="translate(15,${(h-b+t)/2}) rotate(-90)" text-anchor="middle" font-size="11" fill="#666">${esc(ylabel)}</text>`}
const tick=v=>Math.abs(v)>=1000?(v/1000).toFixed(1)+'k':Number(v.toFixed(2));
function lineChart(points,xlabel,ylabel,title='',roc=false){const w=500,h=335,l=68,r=24,t=15,b=55,xmin=Math.min(0,...points.map(p=>p[0])),xmax=Math.max(...points.map(p=>p[0])),ymin=Math.min(0,...points.map(p=>p[1])),ymax=Math.max(...points.map(p=>p[1])),xp=x=>l+(x-xmin)/(xmax-xmin||1)*(w-l-r),yp=y=>h-b-(y-ymin)/(ymax-ymin||1)*(h-t-b);return `<div class="chart-frame"><div class="micro">${esc(title||ylabel)}</div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title||ylabel)}">${axes(w,h,l,r,t,b,xmin,xmax,ymin,ymax,xlabel,ylabel)}${roc?`<path d="M${l},${h-b}L${w-r},${t}" stroke="#aaa" stroke-dasharray="5 4"/>`:''}<path d="${points.map((p,i)=>(i?'L':'M')+xp(p[0])+','+yp(p[1])).join(' ')}" stroke="#222" stroke-width="1.6" fill="none"/></svg></div>`}
function plotCategory(p){if(/pca|tsne/.test(p.name))return 'Projections';if(/importance|structure|loss/.test(p.name))return 'Model';if(/diagnostics|confusion|roc/.test(p.name))return 'Diagnostics';if(/elbow|dendrogram/.test(p.name))return 'Clustering';return 'Data'}
function plotTitle(name){return pretty(name.replace(/^regression_/,'').replace(/^diamond_/,'Diamond ').replace(/_pca$/,' / PCA').replace(/_tsne$/,' / t-SNE').replace(/_roc$/,' / ROC curve').replace(/_confusion$/,' / confusion matrix'))}
function plots(){const categories=['All',...new Set(currentData.plots.map(plotCategory))],filtered=currentData.plots.filter(p=>state.filter==='All'||plotCategory(p)===state.filter),shown=state.allPlots?filtered:filtered.slice(0,6);return `<div class="panel-head"><div><h3>A different view of the evidence.</h3><p>Inspect the actual figures from the executed notebooks. Open any plot to zoom and download.</p></div><span class="badge">${currentData.plots.length} VERIFIED FIGURES</span></div><div class="plot-toolbar">${categories.map(c=>`<button class="filter-chip ${c===state.filter?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div><div class="plot-grid">${shown.map(p=>`<button class="plot-card" data-plot="${esc(p.name)}"><img loading="lazy" src="${esc(p.url)}" alt="${esc(plotTitle(p.name))}"><span class="plot-caption"><span>${esc(plotTitle(p.name))}</span><b>↗</b></span></button>`).join('')}</div>${shown.length<filtered.length?`<button class="button plot-more" id="more-plots">Show all ${filtered.length} figures <span>↓</span></button>`:''}<p class="quiet-note">${state.track==='clustering'?'PCA/t-SNE can distort distances. Cluster metrics are computed in the full transformed feature space; colors identify fitted cluster labels.':'These figures show the actual data and fitted-model outputs. The model-detail tab also provides interactive diagnostics from saved held-out predictions.'}</p>`}
function friendly(field){const map={AspectRation:'Aspect ratio',MajorAxisLength:'Major axis length',MinorAxisLength:'Minor axis length',EquivDiameter:'Equivalent diameter',ConvexArea:'Convex area',Marital_Status:'Marital status',Kidhome:'Children at home',Teenhome:'Teenagers at home',NumDealsPurchases:'Deal purchases',NumWebVisitsMonth:'Monthly web visits',Customer_Tenure_Days:'Customer tenure (days)',Total_Spend:'Total spend',Total_Purchases:'Total purchases',Age:'Age at dataset reference year',Recency:'Days since last purchase'};return map[field]||pretty(field)}
function prediction(){const d=currentData,clust=state.track==='clustering',models=clust?d.models.filter(m=>m.name==='K-Means'):d.models;return `<div class="panel-head"><div><h3>${clust?'A new profile. A familiar pattern.':'Your inputs. A real model result.'}</h3><p>${clust?'Assign a customer to the saved K-Means segments using the same fitted preprocessing.':'Try a sample or enter your own measurements. Predictions run privately on your device using the actual fitted model.'}</p></div><span class="badge dark">LIVE TRAINED-MODEL INFERENCE</span></div><div class="toolbar"><div><label class="control-label" for="predict-model">PREDICT WITH</label><select class="model-selector" id="predict-model">${modelOptions(state.predictModel,models)}</select></div><button class="text-button" id="fill-example">Load a dataset example ↗</button></div>${clust?`<p class="quiet-note">Age and tenure reference ${esc(d.reference_date)}. Spend and purchase counts are totals over the dataset period. Agglomerative segments can be explored in model detail; that method has no native new-record prediction.</p>`:''}<div class="prediction-layout"><form id="prediction-form"><div class="input-grid">${d.input_fields.map(f=>`<label>${esc(friendly(f.name))}${f.type==='category'?`<select name="${esc(f.name)}">${f.choices.map(c=>`<option ${c===f.default?'selected':''}>${esc(c)}</option>`).join('')}</select>`:`<input required name="${esc(f.name)}" type="number" step="any" min="0" value="${f.default}" inputmode="decimal"><small>OBSERVED ${number(f.minimum_observed,2)} — ${number(f.maximum_observed,2)}</small>`}</label>`).join('')}</div><div class="form-actions"><button class="button black" type="submit" id="run-prediction">${clust?'Find segment':'Run prediction'} <span>↗</span></button><button class="text-button" type="reset">Reset inputs</button></div><div id="form-error" class="form-error" role="alert"></div><p class="quiet-note">${state.track==='regression'?'Volume is computed automatically from the dimensions. Price currency has not been verified; output uses the original dataset units.':state.track==='classification'?'Compactness is computed automatically. Class labels remain 0 and 1; a verified mapping to variety names was not supplied.':'Centroid distances describe similarity in the transformed feature space. They are not probabilities or a supervised class prediction.'}</p></form><div id="prediction-result" class="prediction-result"><div class="micro">OUTPUT / WAITING FOR INPUT</div><h4>A little curiosity goes a long way.</h4><p>Start with an example, or change a measurement.<br>The fitted model will take it from there.</p></div></div>`}
async function runPrediction(event){event.preventDefault();const button=$('#run-prediction'),error=$('#form-error');error.textContent='';button.disabled=true;button.innerHTML='<span class="loader"></span>Evaluating model';try{const form=new FormData($('#prediction-form')),record={};for(const field of currentData.input_fields){const value=form.get(field.name);if(field.type==='category'){if(!field.choices.includes(value))throw Error('Choose a valid '+friendly(field.name));record[field.name]=value}else{if(value===''||!Number.isFinite(Number(value)))throw Error(friendly(field.name)+' must be a finite number.');record[field.name]=Number(value);if(record[field.name]<0)throw Error(friendly(field.name)+' cannot be negative.')}}validateInputs(record);const name=$('#predict-model').value,key=state.track==='regression'?'regression_'+slug(name).replace('_regression',''):state.track==='clustering'?'kmeans':slug(name);if(!modelCache.has(key))modelCache.set(key,await fetchJSON('models/'+key+'.json'));const output=predict(modelCache.get(key),record);if(!Number.isFinite(output.value))throw Error('This input could not be evaluated. Check the measurements.');renderPrediction(output,name);$('#prediction-result').scrollIntoView({behavior:'smooth',block:innerWidth<721?'center':'nearest'});}catch(e){error.textContent=e.message}finally{button.disabled=false;button.innerHTML=(state.track==='clustering'?'Find segment':'Run prediction')+' <span>↗</span>'}}
function validateInputs(r){if(state.track==='regression'){for(const f of ['carat','depth','table','x','y','z'])if(r[f]<=0)throw Error(friendly(f)+' must be positive.')}if(state.track==='classification'){for(const f of currentData.input_fields)if(f.name!=='Eccentricity'&&r[f.name]<=0)throw Error(friendly(f.name)+' must be positive.');for(const f of ['Eccentricity','Extent','Roundness'])if(r[f]>1)throw Error(friendly(f)+' must be between 0 and 1.')}if(state.track==='clustering'){if(r.Age<18||r.Age>100)throw Error('Age must be 18 to 100 at the dataset reference year.');for(const f of ['Kidhome','Teenhome','Recency','NumDealsPurchases','NumWebVisitsMonth','Customer_Tenure_Days','Total_Purchases'])if(!Number.isInteger(r[f]))throw Error(friendly(f)+' must be a whole number.')}}
function renderPrediction(result,name){const p=$('#prediction-result');let body;if(state.track==='regression')body=`<div class="micro">ESTIMATED DIAMOND PRICE</div><div class="prediction-value">${number(result.value,2)}</div><p>Original dataset price units</p>`;else if(state.track==='classification')body=`<div class="micro">PREDICTED RICE CLASS</div><div class="prediction-value">Class ${result.value}</div>${result.probabilities.map((v,i)=>`<div class="probability-row"><div><span>Class ${currentData.class_labels[i]}</span><span>${number(v*100,2)}%</span></div><div class="probability-bar"><i style="width:${v*100}%"></i></div></div>`).join('')}<p class="quiet-note">Model-estimated probabilities, not a calibrated guarantee.</p>`;else body=`<div class="micro">CUSTOMER SEGMENT ASSIGNMENT</div><div class="prediction-value">Cluster ${result.value}</div>${result.distances.map((v,i)=>`<div class="probability-row"><div><span>Distance to cluster ${i}</span><span>${number(v,3)}</span></div><div class="probability-bar"><i style="width:${v/Math.max(...result.distances)*100}%"></i></div></div>`).join('')}<p class="quiet-note">The closest fitted centroid determines the assignment.</p>`;p.innerHTML=body+`<div class="result-model">${esc(name)} · saved fitted model</div><div class="micro">✓ EVALUATED LOCALLY / INPUTS NOT UPLOADED</div>`}
function bindContent(){
 $('#metric-select')?.addEventListener('change',e=>{state.metric=e.target.value;state.sortReverse=false;render()});
 $$('[data-sort]',$('#lab-content')).forEach(b=>b.addEventListener('click',()=>{if(currentData.metrics.includes(b.dataset.sort)){state.sortReverse=state.metric===b.dataset.sort?!state.sortReverse:false;state.metric=b.dataset.sort;render()}}));
 $$('[data-stage-model]').forEach(b=>b.addEventListener('click',()=>{state.stage=b.dataset.stageModel;render()}));
 $$('[data-check-model]').forEach(b=>b.addEventListener('change',()=>{b.checked?state.models.add(b.dataset.checkModel):state.models.delete(b.dataset.checkModel);render()}));
 $('#pair-a')?.addEventListener('change',pairResult);$('#pair-b')?.addEventListener('change',pairResult);pairResult();
 $('#detail-select')?.addEventListener('change',e=>{state.detail=e.target.value;render()});
 $$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;state.allPlots=false;render()}));
 $('#more-plots')?.addEventListener('click',()=>{state.allPlots=true;render()});
 $$('[data-plot]').forEach(b=>b.addEventListener('click',()=>{const p=currentData.plots.find(p=>p.name===b.dataset.plot);$('#dialog-image').src=p.url;$('#dialog-image').alt=plotTitle(p.name);$('#dialog-title').textContent=plotTitle(p.name);$('#dialog-download').href=p.url;$('#plot-dialog').showModal()}));
 $$('[data-jump]').forEach(b=>b.addEventListener('click',()=>openTab(b.dataset.jump)));
 $('#prediction-form')?.addEventListener('submit',runPrediction);
 $('#prediction-form')?.addEventListener('input',()=>{$('#prediction-result').innerHTML='<div class="micro">OUTPUT / INPUTS CHANGED</div><h4>A new perspective.</h4><p>Run the model to evaluate these measurements.</p>'});
 $('#prediction-form')?.addEventListener('reset',()=>{$('#form-error').textContent='';$('#prediction-result').innerHTML='<div class="micro">OUTPUT / INPUTS RESET</div><h4>Ready for another perspective.</h4><p>Change the measurements and run the model again.</p>'});
 $('#predict-model')?.addEventListener('change',e=>{state.predictModel=e.target.value;$('#prediction-result').innerHTML='<div class="micro">OUTPUT / MODEL CHANGED</div><h4>A different approach.</h4><p>Run the selected model to compare its prediction.</p>'});
 $('#fill-example')?.addEventListener('click',()=>{const form=$('#prediction-form');for(const [key,value] of Object.entries(currentData.example_input)){const input=form.elements.namedItem(key);if(input)input.value=value}$('#form-error').textContent='';$('#prediction-result').innerHTML='<div class="micro">OUTPUT / EXAMPLE LOADED</div><h4>Ready to explore.</h4><p>Run the selected model to evaluate this dataset example.</p>';toast('Dataset example loaded. Ready to evaluate.')});
 $('[data-retry]')?.addEventListener('click',()=>loadTrack(state.track));
}
$$('[data-track]').forEach(b=>b.addEventListener('click',()=>{state.tab='overview';loadTrack(b.dataset.track,true)}));
$$('[data-lab-track]').forEach(b=>b.addEventListener('click',()=>loadTrack(b.dataset.labTrack)));
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>openTab(b.dataset.tab)));
$$('[data-open-tab]').forEach(b=>b.addEventListener('click',()=>openTab(b.dataset.openTab)));
$('#close-dialog').addEventListener('click',()=>$('#plot-dialog').close());
$('#plot-dialog').addEventListener('click',e=>{if(e.target===$('#plot-dialog'))$('#plot-dialog').close()});
const stages=[{name:'DISCOVER',label:'THREE DATASETS. THREE QUESTIONS.',head:'Start with<br>the right question.',description:'What determines a price?<br>What distinguishes a grain?<br>What brings customers together?',check:'SOURCE DATA AUDITED',number:'03/03',unit:'TRACKS CONNECTED'},
{name:'PREPARE',label:'A FAIR FOUNDATION FOR EVERY MODEL.',head:'Make the data<br>ready to learn.',description:'Check missing values and duplicates.<br>Engineer meaningful features.<br>Fit transforms on training folds.',check:'PREPROCESSING VERIFIED',number:'42',unit:'FIXED RANDOM SEED'},
{name:'COMPARE',label:'DIFFERENT MODELS. SHARED EVIDENCE.',head:'Put every<br>approach to the test.',description:'Compare metrics on the same data.<br>Inspect errors and validation.<br>See what tuning really changes.',check:'SAVED METRICS RECOMPUTED',number:'22/22',unit:'MODELS EVALUATED'},
{name:'PREDICT',label:'YOUR INPUTS. THE FITTED MODEL.',head:'Ask the next<br>question yourself.',description:'Enter a diamond, grain or profile.<br>Use the fitted transformations.<br>Get a real model result locally.',check:'BROWSER INFERENCE VERIFIED',number:'21',unit:'PREDICTION PATHS'}];
$$('[data-stage]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.stage),s=stages[i];$$('[data-stage]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));$('#stage-title').textContent=`STAGE 0${i+1} / ${s.name}`;$('#flow-label').textContent=s.label;$('#flow-headline').innerHTML=s.head;$('#flow-description').innerHTML=s.description;$('.flow-check').textContent='✓  '+s.check;$('#flow-number').textContent=s.number;$('#flow-unit').textContent=s.unit}));
// Keyboard navigation for the two tablists.
$$('[role=tablist]').forEach(list=>list.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=$$('[role=tab]',list),index=tabs.indexOf(document.activeElement);if(index<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click()}));
try{catalog=await fetchJSON('data/catalog.json');await loadTrack('regression')}catch(error){$('#data-status').textContent='RESULTS UNAVAILABLE';$('#lab-content').innerHTML='<p class="model-empty">The data catalogue could not be loaded. Refresh the page to retry.</p>'}
